class ParticleIntrinsic {
  constructor(public color: string, public textureId: number) {}
}
class Particle {
  constructor(private intrinsic: ParticleIntrinsic, private x: number, private y: number) {}
  draw(ctx: CanvasRenderingContext2D) { /* use intrinsic and extrinsic data */ }
}
class IntrinsicFactory {
  private cache = new Map<string, ParticleIntrinsic>();
  get(key: string) { if (!this.cache.has(key)) this.cache.set(key, new ParticleIntrinsic(key, 0)); return this.cache.get(key)!; }
}

class Color { constructor(public r:number, public g:number, public b:number) {} }
class ColorFactory {
  private cache = new Map<string, Color>();
  getColor(name: string) {
    if (!this.cache.has(name)) this.cache.set(name, new Color(0,0,0));
    return this.cache.get(name)!;
  }
}
// Usage: many Pixels reuse Color instances from factory

